 function candidate(p,b){const config=profile(p?.binding);if(!config||!b?.actors)return null;return [config.primary,'lookout'].map(id=>b.actors.find(a=>a.id===id&&a.team==='opposition'&&a.status==='escaped'&&a.hp>0)).find(Boolean)||null;}
